    private final String chemin;

    Icone(String chemin) {
        this.chemin = chemin;
    }

    public String getChemin() {
        return chemin;
    }

    /** Icône carrée de la taille donnée ; sa couleur vient de -fx-background-color (classe « icone »). */
    public Region creer(double taille) {
        Region r = new Region();
        r.setStyle("-fx-shape: \"" + chemin + "\";");
        r.getStyleClass().add("icone");
        r.setMinSize(taille, taille);
        r.setPrefSize(taille, taille);
        r.setMaxSize(taille, taille);
        return r;
    }
